mapper.select:
select mps.sku_id as skuId, mps.product_id as productId, mp.product_name as productName, mps.sku_name as skuName, mps.market_price as marketPrice, mps.sale_price as salePrice, mps.stock as stock, mps.sales_count as salesCount, mps.status as status, mps.del_flag as delFlag, mps.create_time as createTime, mps.update_time as updateTime, mps.remark as remark from mall_product_sku mps left join mall_product mp on mps.product_id = mp.product_id and mp.del_flag = 0 where mps.del_flag = 0
and mps.product_id = #{productId}
and mp.product_name like concat('%', #{productName}, '%')
and mps.sku_name like concat('%', #{skuName}, '%')
and mps.status = #{status}
order by mps.sku_id desc

select count(1) from mall_product_sku mps where mps.del_flag = 0
and mps.product_id = #{productId}
and mps.sku_name like concat('%', #{skuName}, '%')

mapper.update:
update mall_product_sku
set del_flag = 1
where sku_id = #{skuId}
